window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8e8a505dc9ca3b57"]={"versions": [{"id": "FIG-8e8a505dc9ca3b57", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Wire-Format- / Serialisierungslayout (PDU-Payload-Struktur auf Byte-Ebene).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der On-Wire-Repräsentation eines eindimensionalen Arrays fester Elementanzahl (<code>Static Array [n]</code>) gemäß [PRS_SOMEIP_00099].</li>\n<li><strong>Architektur-Einordnung:</strong></li>\n<li>Verortung in der Kommunikationsschicht (SOME/IP-Protokoll, Service-Oriented Architecture).</li>\n<li><strong>Classic AUTOSAR (CP):</strong> Definiert die Serialisierungslogik des <code>SomeIpXf</code> (SOME/IP Transformer) bzw. <code>SomeIpTp</code> unterhalb des RTE-Signal-/Parameter-Routings.</li>\n<li><strong>Adaptive AUTOSAR (AP):</strong> Definiert das On-Wire-Layout der Kommunikations-Middleware (<code>ara::com</code> SOME/IP-Binding) für Payload-Daten über UDP/TCP-Sockets.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Static Array [n]</code>:</strong> Repräsentiert einen sequenziellen, homogenen Datentyp fixer Kardinalität $n \\ge 1$ (<code>ImplementationDataType</code> mit Kategorie <code>ARRAY</code> bzw. <code>std::array&lt;T, n&gt;</code>).</li>\n<li><strong><code>LengthField (optional)</code>:</strong></li>\n<li>Optionales Längenfeld mit konfigurierbarer Breite (0, 8, 16 oder 32 Bit; definiert via ARXML-Transformationsbeschreibung <code>SomeIpTransformationDescription.lengthFieldSize</code>).</li>\n<li>Kodiert die Gesamtlänge des nachfolgenden Payloads in Bytes: $\\text{Wert} = n \\cdot e$.</li>\n<li><strong><code>Element_1</code> bis <code>Element_n</code>:</strong></li>\n<li>Homogene Nutzdatenelemente eines identischen Datentyps mit jeweils fixer Größe $e$ Bytes (<code>element size e</code>).</li>\n<li><strong>Kardinalitäten & Größenmetriken:</strong></li>\n<li>Anzahl der Elemente: statisch $n$ (Compile-Zeit-Invariant).</li>\n<li>Gesamte Nutzdatenlänge: $n \\cdot e$.</li>\n<li>Gesamte Wire-Größe: $\\text{sizeof}(\\text{LengthField}) + (n \\cdot e)$ (bzw. $n \\cdot e$ falls <code>lengthFieldSize == 0</code>).</li>\n<li>Die Elemente werden direkt aneinandergereiht (kein inter-elementares Alignment-Padding auf SOME/IP-Ebene, sofern nicht explizit im Typenmodell definiert).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Serialisierung (TX-Pfad):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Der Transformer ermittelt die statische Nutzdatenlänge $n \\cdot e$.</li>\n<li>Falls <code>lengthFieldSize &gt; 0</code>: Serialisierung des Längenfeldes mit Wert $n \\cdot e$ in der konfigurierten Byte-Order (Default: Big-Endian / Network Byte Order).</li>\n<li>Sequenzielle Serialisierung der Elemente $\\text{Element}_1 \\dots \\text{Element}_n$ unmittelbar anschließend.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Deserialisierung & Validierung (RX-Pfad):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Falls ein Längenfeld konfiguriert ist, liest der Deserializer das Feld und prüft:</li>\n</ol>\n<p class=\"fig-p\">$$\\text{LengthField} \\stackrel{!}{=} n \\cdot e$$</p>\n<ol class=\"fig-list\">\n<li>Plausibilisierung gegen die verbleibende PDU-Restlänge.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehlerpfade & Abbruchbedingungen:</strong></li>\n<li>Weicht der Wert des Längenfelds von $n \\cdot e$ ab oder ist die PDU kürzer als $\\text{LengthField} + n \\cdot e$, bricht die Deserialisierung ab.</li>\n<li>Fehlerreaktion: SOME/IP-ReturnCode <code>0x07</code> (<code>MALFORMED_MESSAGE</code>) bzw. Rückgabe von <code>E_NOT_OK</code> / Transformer-Fehler an die RTE / <code>ara::com</code>.</li>\n<li>Optionales Logging über DET (Development Error Tracer) in CP.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Konfiguration:</strong></li>\n<li>Parameter <code>lengthFieldSize</code>: Bei fixed-length Arrays kann das Längenfeld zur Overhead-Reduktion entfallen (<code>lengthFieldSize = 0</code>). Eine Abweichung zwischen Sender und Empfänger führt zwangsläufig zu Framing-/Parsing-Fehlern.</li>\n<li>Konsistente Endianness-Definition (<code>SomeIpTransformationDescription.byteOrder</code>) für Längenfeld und Basiselemente sicherstellen.</li>\n<li><strong>Speicherallokation & Determinismus:</strong></li>\n<li>Da die Gesamtgröße $\\text{LengthField} + n \\cdot e$ a priori zur Compile-Zeit fixiert ist, kann im Embedded-Treiber/Stack statischer Pufferplatz alloziert werden (keine dynamische Heap-Nutzung, ASIL/ISO 26262-konform).</li>\n<li><strong>Multi-dimensionale Arrays ([PRS_SOMEIP_00101]):</strong></li>\n<li>Für mehrdimensionale statische Arrays gilt Row-Major-Order (C/C++-Standard-Layout). Jede Dimension kann bei entsprechender ARXML-Parametrierung rekursiv ein eigenes Längenfeld aufweisen.</li>\n</ul>"}, {"id": "FIG-1d0639f219eb1ed2", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Wire-Format- / Serialisierungslayout (PDU-Payload-Struktur auf Byte-Ebene).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der On-Wire-Repräsentation eines eindimensionalen Arrays fester Elementanzahl (<code>Static Array [n]</code>) gemäß [PRS_SOMEIP_00099].</li>\n<li><strong>Architektur-Einordnung:</strong></li>\n<li>Verortung in der Kommunikationsschicht (SOME/IP-Protokoll, Service-Oriented Architecture).</li>\n<li><strong>Classic AUTOSAR (CP):</strong> Definiert die Serialisierungslogik des <code>SomeIpXf</code> (SOME/IP Transformer) bzw. <code>SomeIpTp</code> unterhalb des RTE-Signal-/Parameter-Routings.</li>\n<li><strong>Adaptive AUTOSAR (AP):</strong> Definiert das On-Wire-Layout der Kommunikations-Middleware (<code>ara::com</code> SOME/IP-Binding) für Payload-Daten über UDP/TCP-Sockets.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Static Array [n]</code>:</strong> Repräsentiert einen sequenziellen, homogenen Datentyp fixer Kardinalität $n \\ge 1$ (<code>ImplementationDataType</code> mit Kategorie <code>ARRAY</code> bzw. <code>std::array&lt;T, n&gt;</code>).</li>\n<li><strong><code>LengthField (optional)</code>:</strong></li>\n<li>Optionales Längenfeld mit konfigurierbarer Breite (0, 8, 16 oder 32 Bit; definiert via ARXML-Transformationsbeschreibung <code>SomeIpTransformationDescription.lengthFieldSize</code>).</li>\n<li>Kodiert die Gesamtlänge des nachfolgenden Payloads in Bytes: $\\text{Wert} = n \\cdot e$.</li>\n<li><strong><code>Element_1</code> bis <code>Element_n</code>:</strong></li>\n<li>Homogene Nutzdatenelemente eines identischen Datentyps mit jeweils fixer Größe $e$ Bytes (<code>element size e</code>).</li>\n<li><strong>Kardinalitäten & Größenmetriken:</strong></li>\n<li>Anzahl der Elemente: statisch $n$ (Compile-Zeit-Invariant).</li>\n<li>Gesamte Nutzdatenlänge: $n \\cdot e$.</li>\n<li>Gesamte Wire-Größe: $\\text{sizeof}(\\text{LengthField}) + (n \\cdot e)$ (bzw. $n \\cdot e$ falls <code>lengthFieldSize == 0</code>).</li>\n<li>Die Elemente werden direkt aneinandergereiht (kein inter-elementares Alignment-Padding auf SOME/IP-Ebene, sofern nicht explizit im Typenmodell definiert).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Serialisierung (TX-Pfad):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Der Transformer ermittelt die statische Nutzdatenlänge $n \\cdot e$.</li>\n<li>Falls <code>lengthFieldSize &gt; 0</code>: Serialisierung des Längenfeldes mit Wert $n \\cdot e$ in der konfigurierten Byte-Order (Default: Big-Endian / Network Byte Order).</li>\n<li>Sequenzielle Serialisierung der Elemente $\\text{Element}_1 \\dots \\text{Element}_n$ unmittelbar anschließend.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Deserialisierung & Validierung (RX-Pfad):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Falls ein Längenfeld konfiguriert ist, liest der Deserializer das Feld und prüft:</li>\n</ol>\n<p class=\"fig-p\">$$\\text{LengthField} \\stackrel{!}{=} n \\cdot e$$</p>\n<ol class=\"fig-list\">\n<li>Plausibilisierung gegen die verbleibende PDU-Restlänge.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehlerpfade & Abbruchbedingungen:</strong></li>\n<li>Weicht der Wert des Längenfelds von $n \\cdot e$ ab oder ist die PDU kürzer als $\\text{LengthField} + n \\cdot e$, bricht die Deserialisierung ab.</li>\n<li>Fehlerreaktion: SOME/IP-ReturnCode <code>0x07</code> (<code>MALFORMED_MESSAGE</code>) bzw. Rückgabe von <code>E_NOT_OK</code> / Transformer-Fehler an die RTE / <code>ara::com</code>.</li>\n<li>Optionales Logging über DET (Development Error Tracer) in CP.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Konfiguration:</strong></li>\n<li>Parameter <code>lengthFieldSize</code>: Bei fixed-length Arrays kann das Längenfeld zur Overhead-Reduktion entfallen (<code>lengthFieldSize = 0</code>). Eine Abweichung zwischen Sender und Empfänger führt zwangsläufig zu Framing-/Parsing-Fehlern.</li>\n<li>Konsistente Endianness-Definition (<code>SomeIpTransformationDescription.byteOrder</code>) für Längenfeld und Basiselemente sicherstellen.</li>\n<li><strong>Speicherallokation & Determinismus:</strong></li>\n<li>Da die Gesamtgröße $\\text{LengthField} + n \\cdot e$ a priori zur Compile-Zeit fixiert ist, kann im Embedded-Treiber/Stack statischer Pufferplatz alloziert werden (keine dynamische Heap-Nutzung, ASIL/ISO 26262-konform).</li>\n<li><strong>Multi-dimensionale Arrays ([PRS_SOMEIP_00101]):</strong></li>\n<li>Für mehrdimensionale statische Arrays gilt Row-Major-Order (C/C++-Standard-Layout). Jede Dimension kann bei entsprechender ARXML-Parametrierung rekursiv ein eigenes Längenfeld aufweisen.</li>\n</ul>"}], "trans": [{"from": "FIG-8e8a505dc9ca3b57", "to": "FIG-1d0639f219eb1ed2", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
